# Render the compact row layout for the preferred 12--16 October 2023
# chronological sampling schematic (PDF, PNG, and caption).
#
# The underlying maps, selected nights, annotations, and data are generated by
# figure_sampling_schematic_simple.R. This file changes presentation only and
# writes only sampling_schematic_simple_chronological_2023_oct12_16_compact_row*
# outputs to SAMPLING_SCHEMATIC_COMPACT_OUT_DIR (the script directory by default).

suppressPackageStartupMessages({
  library(ggplot2)
  library(patchwork)
})

script_arg <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
script_dir <- if (length(script_arg)) {
  dirname(normalizePath(sub("^--file=", "", script_arg[1])))
} else {
  normalizePath("figures")
}

compact_out_dir <- Sys.getenv(
  "SAMPLING_SCHEMATIC_COMPACT_OUT_DIR", unset = script_dir
)
dir.create(compact_out_dir, recursive = TRUE, showWarnings = FALSE)

# Recreate exactly the preferred chronological period. The base script always
# saves its own figure, so send that intermediate render to a temporary folder.
render_tmp <- tempfile("sampling-schematic-compact-source-")
dir.create(render_tmp)
Sys.setenv(
  SAMPLING_SCHEMATIC_CHRONOLOGICAL = "true",
  SAMPLING_SCHEMATIC_YEAR = "2023",
  SAMPLING_SCHEMATIC_NONE_DATE = "2023-10-12",
  SAMPLING_SCHEMATIC_NORTH_DATE = "2023-10-15",
  SAMPLING_SCHEMATIC_EAST_DATE = "2023-10-16",
  SAMPLING_SCHEMATIC_TAG = "compact_source",
  SAMPLING_SCHEMATIC_OUT_DIR = render_tmp
)
if (!nzchar(Sys.getenv("SAMPLING_SCHEMATIC_DATA_PATH"))) {
  Sys.setenv(
    SAMPLING_SCHEMATIC_DATA_PATH = "/data/birdcloudstorage-tvm/ibm-ml/data/"
  )
}
tryCatch(
  source(file.path(script_dir, "figure_sampling_schematic_simple.R")),
  finally = unlink(render_tmp, recursive = TRUE)
)

# The chronological reading order for this selected period is grounded,
# north-origin migration, east-origin migration.
compact_panel <- function(p, title) {
  p +
    labs(title = title) +
    theme(
      plot.title = element_text(size = 10.5, lineheight = 0.95),
      plot.title.position = "panel",
      plot.subtitle = element_text(size = 8),
      plot.margin = margin(2, 1, 2, 1),
      legend.title = element_text(size = 8),
      legend.text = element_text(size = 7.5)
    )
}

# Horizontal-row callouts: place a single opaque information card fully inside
# each map. The white backing prevents wind vectors and tracks from competing
# with the annotation text.
row_sample_card <- function(p, counts) {
  count_labels <- c("Sampled:", counts$big, counts$small)
  keep_layer <- vapply(p$layers, function(layer) {
    if (inherits(layer$geom, "GeomRect")) return(FALSE)
    layer_data <- layer$data
    layer_labels <- layer$aes_params$label
    if (is.null(layer_labels) && is.data.frame(layer_data) &&
        "label" %in% names(layer_data)) {
      layer_labels <- layer_data$label
    }
    is.null(layer_labels) ||
      !any(as.character(layer_labels) %in% count_labels)
  }, logical(1))
  p$layers <- p$layers[keep_layer]

  card_counts <- counts
  card_counts$small[card_counts$small == "simulated migrants"] <-
    "flying simulated migrants"

  n_c <- nrow(card_counts)
  vstep <- 0.42
  y_bottom <- panel_bbox[["ymin"]] + 0.38
  row_y <- y_bottom + (n_c - seq_len(n_c)) * vstep
  y_header <- max(row_y) + 0.43
  x_num_right <- panel_bbox[["xmin"]] + 1.52
  x_desc_left <- x_num_right + 0.09
  x_left <- panel_bbox[["xmin"]] + 0.18
  # The grounded-bird label is substantially longer than the two flying-night
  # labels. Size the card to its content so right padding remains visually even
  # and the shorter cards leave room for the Night 3 inset colour bar.
  card_width <- if (any(grepl("^grounded", card_counts$small))) 5.55 else 4.85
  x_right <- panel_bbox[["xmin"]] + card_width
  box_bottom <- min(row_y) - 0.27
  box_top <- y_header + 0.27

  p <- p +
    annotate(
      "rect", xmin = x_left, xmax = x_right,
      ymin = box_bottom, ymax = box_top,
      fill = "white", alpha = 0.90,
      colour = "grey55", linewidth = 0.25
    ) +
    annotate(
      "text", x = x_left + 0.16, y = y_header, label = "Nightly sample",
      hjust = 0, vjust = 0.5, fontface = "bold",
      size = 2.85, colour = "grey10"
    )
  for (i in seq_len(n_c)) {
    p <- p +
      annotate(
        "text", x = x_num_right, y = row_y[i], label = card_counts$big[i],
        hjust = 1, vjust = 0.5, fontface = "bold",
        size = 4.15, colour = card_counts$big_col[i]
      ) +
      annotate(
        "text", x = x_desc_left, y = row_y[i],
        label = card_counts$small[i],
        hjust = 0, vjust = 0.5, fontface = "plain",
        size = 2.25, colour = card_counts$big_col[i]
      )
  }
  p
}

row_panel <- function(p, title, counts) {
  p <- compact_panel(p, title) +
    labs(subtitle = NULL)
  row_sample_card(p, counts)
}

row_none <- row_panel(
  p_suppressed, "Night 1: 12-13 Oct 2023", counts_suppressed
)
row_north <- row_panel(
  p_active, "Night 2: 15-16 Oct 2023", counts_active
)
row_east <- row_panel(
  p_directional, "Night 3: 16-17 Oct 2023", counts_directional
)

# Patchwork cannot currently remove duplicate axes from fixed-aspect coord_sf
# panels. Retain its native collection request below, with this visual fallback
# for the two redundant y axes.
redundant_y_axis <- theme(
  axis.text.y = element_blank(),
  axis.ticks.y = element_blank(),
  axis.title.y = element_blank()
)

inside_legend <- function(position, justification) {
  theme(
    legend.position = "inside",
    legend.position.inside = position,
    legend.justification = justification,
    legend.background = element_rect(
      fill = scales::alpha("white", 0.92),
      colour = "grey55", linewidth = 0.25
    ),
    legend.box.background = element_blank(),
    legend.margin = margin(3, 5, 3, 5),
    legend.box.margin = margin(0, 0, 0, 0),
    legend.spacing.y = unit(0.1, "lines")
  )
}

# Split the encodings between the two outer panels. This uses otherwise quiet
# map space and removes the need for any external legend row.
fill_scale <- row_none$scales$get_scales("fill")
fill_scale$labels <- c("Radar core", "Sampled this night")
row_none_inset <- row_none +
  labs(fill = "ERA5 cells") +
  guides(
    colour = "none",
    fill = guide_legend(
      title = "ERA5 cells",
      ncol = 1,
      override.aes = list(
        colour = c("#3a7a8c", "#b58900"),
        linewidth = 0.3,
        alpha = 0.55
      ),
      keywidth = unit(0.8, "lines"),
      keyheight = unit(0.8, "lines")
    )
  ) +
  inside_legend(c(0.975, 0.975), c("right", "top"))

row_north_clean <- row_north +
  guides(colour = "none", fill = "none") +
  redundant_y_axis +
  theme(legend.position = "none")

row_east_inset <- row_east +
  guides(
    fill = "none",
    colour = guide_colorbar(
      title = "850 hPa wind speed (m/s)",
      direction = "horizontal",
      barwidth = unit(5.2, "lines"),
      barheight = unit(0.55, "lines"),
      title.position = "top",
      title.hjust = 0
    )
  ) +
  redundant_y_axis +
  inside_legend(c(0.975, 0.035), c("right", "bottom"))

save_layout <- function(plot, stem, width, height) {
  pdf_path <- file.path(compact_out_dir, paste0(stem, ".pdf"))
  png_path <- file.path(compact_out_dir, paste0(stem, ".png"))
  ggsave(pdf_path, plot, width = width, height = height, units = "in")
  ggsave(png_path, plot, width = width, height = height, units = "in", dpi = 300)
  message(sprintf("Wrote %s and %s", pdf_path, png_path))
}

# Compact triptych. The y axis is shared visually and requested via
# patchwork's native axis collection. Legends are inset into the outer panels.
compact_row <- wrap_plots(
  row_none_inset,
  row_north_clean,
  row_east_inset,
  nrow = 1,
  axes = "collect_y",
  axis_titles = "collect_y"
)

stem <- "sampling_schematic_simple_chronological_2023_oct12_16_compact_row"
save_layout(compact_row, stem, 11.6, 4.35)

